[Fact]
public void TableRendering_Workflow_ValidatesWrappingAndOutputConfig()
{
    var testWriter = new StringWriter();
    var options = new ConsoleTableOptions
    {
        Columns = new List<string> { "Description" },
        EnableCount = true,
        OutputTo = testWriter
    };

    // Initialize the table with custom options (Rule 12 - Output Configuration)
    var table = new ConsoleTable(options);

    // Rule 4: Set MaxWidth to force word-aware cell wrapping
    table.MaxWidth = 12;
    table.SetWordBreakDelimiter(' ');

    // Add content that exceeds MaxWidth to trigger the wrapping logic
    table.AddRow("Wrap this sentence");

    // Act: Render the table to the configured StringWriter (Rule 12)
    table.Write();

    var result = testWriter.ToString();

    // Assert: Verify Word-Aware Wrapping (Rule 4)
    // With MaxWidth 12, "Wrap this sentence" should split into "Wrap this" and "sentence"
    Assert.Contains("Wrap this", result);
    Assert.Contains("sentence", result);

    // Assert: Verify Row Count Summary is present (Rule 6)
    Assert.Contains("Count: 1", result);

    // Act: Verify the summary can be disabled via configuration (Rule 8)
    var noCountWriter = new StringWriter();
    table.Configure(o =>
    {
        o.EnableCount = false;
        o.OutputTo = noCountWriter;
    });
    table.Write();

    var noCountResult = noCountWriter.ToString();

    // Assert: Verify Count is removed but content remains
    Assert.DoesNotContain("Count:", noCountResult);
    Assert.Contains("Wrap this", noCountResult);
}
